"""Topology-only sweep domains for complete multi-Section Bundle members.

A sweep chain does not replace authored Sections or their identities. It says
which directed Section curves form one continuous member path. Coordinates,
handles, parameter equality and surface generation remain native GN work.
"""
from dataclasses import dataclass


@dataclass(frozen=True)
class SweepChain:
    index: int
    sections: tuple  # (semantic Section ID, traversal along authored direction)
    street_id: int
    bundle_id: int = -1
    partner: int = -1
    reversed_pair: bool = False
    inner_u: float = 0.
    owner: bool = False
    aggregate: bool = False


@dataclass(frozen=True)
class SweepPlan:
    chains: tuple

    def section_bindings(self):
        return {sid: (chain, rank, forward) for chain in self.chains
                for rank, (sid, forward) in enumerate(chain.sections)}

    def path_fields(self, pairs):
        """Canonical chain columns shared by authoring and legacy migration.

        ``pairs`` contains existing directed partner declarations, never pairs
        inferred from geometric proximity. No source indices or curves change.
        """
        bindings = self.section_bindings()
        result = {}
        for sid, (chain, rank, forward) in bindings.items():
            partner, reversed_pair, inner, owner, _bundle = pairs.get(sid, (sid, False, 0., False, -1))
            if partner not in bindings:
                raise ValueError('A Bundle path references an absent partner Section')
            result[sid] = dict(st_path_chain_index=chain.index, st_path_chain_order=rank,
                st_path_chain_forward=forward, st_path_chain_aggregate=chain.aggregate,
                st_path_chain_partner=chain.partner if chain.aggregate else bindings[partner][0].index,
                st_path_chain_reversed=chain.reversed_pair if chain.aggregate else reversed_pair,
                st_path_chain_inner_u=chain.inner_u if chain.aggregate else inner,
                st_path_chain_owner=chain.owner if chain.aggregate else owner)
        return result


def plan(net):
    """Keep old single-Section paths unchanged; aggregate complete members.

    Partial extents and internal junctions need explicit span records. They must
    not be inferred by connecting over an attached Section endpoint or a gap.
    """
    streets = {s.id: s for s in net.canonical.streets}
    ownership = net.canonical.section_streets()
    groups, used, paired = [], set(), []
    attached = {m for c in net.connector_records.values() for m in c.members}
    for bundle in net.bundle_records.values():
        if len(bundle.members) != 2:
            raise ValueError('A Bundle sweep requires two complete member Streets')
        chains = [tuple(streets[m[0]].sections) for m in bundle.members]
        if not any(len(items) > 1 for items in chains):
            continue
        pair = []
        for member, sections in zip(bundle.members, chains):
            street_id, forward, head, tail = member
            if not sections or head != tail:
                raise ValueError('Bundle member must keep its lateral order along a complete Street')
            for rank, (sid, sf) in enumerate(sections):
                if sid in used:
                    raise ValueError('A Section cannot belong to overlapping whole-member sweep chains')
                if ((rank and (sid, 0 if sf else 1) in attached)
                        or (rank < len(sections)-1 and (sid, 1 if sf else 0) in attached)):
                    raise ValueError('An internal Bundle junction needs separate member spans')
                record = net.section_records[sid]
                if ((rank and (record.clip_start if sf else record.clip_end) > 0.)
                        or (rank < len(sections)-1 and (record.clip_end if sf else record.clip_start) > 0.)):
                    raise ValueError('An excluded internal extent cannot be joined into a Bundle sweep')
                reference = net.section_records[sections[0][0]]
                if record.preset != reference.preset or abs(record.rise-reference.rise) > 1e-7:
                    raise ValueError('A Bundle chain needs a compatible profile across its Sections')
                used.add(sid)
            group = dict(sections=sections, street_id=street_id, bundle_id=bundle.id,
                         aggregate=True, inner_u=float((head == 0) == forward))
            groups.append(group); pair.append((group, forward))
        paired.append(pair)
    groups.extend(dict(sections=((sid, True),), street_id=ownership[sid])
                  for sid in sorted(net.section_records) if sid not in used)
    groups.sort(key=lambda g: min(s for s, _f in g['sections']))
    for i, group in enumerate(groups):
        group['index'] = i
    for (a, af), (b, bf) in paired:
        a.update(partner=b['index'], reversed_pair=af != bf, owner=True)
        b.update(partner=a['index'], reversed_pair=af != bf, owner=False)
    return SweepPlan(tuple(SweepChain(**g) for g in groups))
